'use client'

import { useRef, useCallback, useState } from 'react'

export type AutoSaveStatus = 'idle' | 'saving' | 'saved' | 'error'

interface UseDebouncedAutoSaveOptions<T> {
  /** Async save function. Receives the current form value. Throws on failure. */
  onSave: (value: T) => Promise<void>
  /** Debounce delay in ms. Default: 800. */
  delay?: number
}

interface UseDebouncedAutoSaveReturn<T> {
  status: AutoSaveStatus
  lastSavedAt: Date | null
  /** Call on every field change. Schedules a debounced save. */
  handleChange: (value: T) => void
  /** Call on field blur for immediate save (cancels pending debounce). */
  handleBlur: (value: T) => Promise<void>
}

export function useDebouncedAutoSave<T>({
  onSave,
  delay = 800,
}: UseDebouncedAutoSaveOptions<T>): UseDebouncedAutoSaveReturn<T> {
  const [status, setStatus] = useState<AutoSaveStatus>('idle')
  const [lastSavedAt, setLastSavedAt] = useState<Date | null>(null)
  const timerRef = useRef<ReturnType<typeof setTimeout> | null>(null)

  const save = useCallback(
    async (value: T) => {
      setStatus('saving')
      try {
        await onSave(value)
        setStatus('saved')
        setLastSavedAt(new Date())
      } catch {
        setStatus('error')
      }
    },
    [onSave],
  )

  const handleChange = useCallback(
    (value: T) => {
      if (timerRef.current) clearTimeout(timerRef.current)
      timerRef.current = setTimeout(() => {
        void save(value)
      }, delay)
    },
    [save, delay],
  )

  const handleBlur = useCallback(
    async (value: T) => {
      if (timerRef.current) {
        clearTimeout(timerRef.current)
        timerRef.current = null
      }
      await save(value)
    },
    [save],
  )

  return { status, lastSavedAt, handleChange, handleBlur }
}

'use client'

import { useState } from 'react'
import { toast } from 'sonner'
