                Email changes are managed through account settings.
              </p>
            </div>

            {!loading && (
              <div className="flex gap-3 pt-2">
                <Button
                  onClick={() => void handleSave()}
                  disabled={!isDirty || saving}
                  loading={saving}
                  loadingLabel="Saving…"
                  className="h-10"
                >
                  Save changes
                </Button>
                {isDirty && (
                  <Button
                    variant="ghost"
                    className="h-10"
                    onClick={() => {
                      setFullName(profile?.full_name ?? '')
                      setIsDirty(false)
                    }}
                  >
                    Cancel
                  </Button>
                )}
              </div>
            )}
          </CardContent>
        </Card>

        {/* Appearance */}
        <Card>
          <CardHeader>
            <CardTitle className="text-sm font-semibold">Appearance</CardTitle>
            <CardDescription>Choose how InkOS looks for you.</CardDescription>
          </CardHeader>
          <CardContent className="space-y-3">
            <ThemeToggle variant="segmented" />
            <p className="text-[12px] text-muted-foreground">
              &ldquo;System&rdquo; follows your operating system preference automatically.
            </p>
          </CardContent>
        </Card>
      </div>
    </div>
  )
