import type { NextRequest } from 'next/server'
import { NextResponse } from 'next/server'
import { z } from 'zod'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { authedRatelimit } from '@/lib/rate-limit'
import { logger } from '@/lib/logger'
import { logAuditAction } from '@/lib/audit'

const UpdateStudioProfileSchema = z.object({
  name: z.string().min(1, 'Studio name is required').max(100).optional(),
  slug: z
    .string()
    .min(2, 'Slug must be at least 2 characters')
    .max(60)
    .regex(/^[a-z0-9-]+$/, 'Slug may only contain lowercase letters, numbers, and hyphens')
    .optional(),
  timezone: z.string().max(80).optional(),
  currency: z.enum(['USD', 'GBP', 'EUR', 'AUD', 'CAD', 'NZD']).optional(),
})

export async function GET() {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  const { success } = await authedRatelimit.limit(auth.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  try {
    const supabase = await createClient()

    const { data: studio, error } = await supabase
      .from('studios')
      .select('id, name, slug, timezone, currency, locale')
      .eq('id', auth.studioId)
      .single()

    if (error || !studio) {
      return NextResponse.json({ error: 'Studio not found' }, { status: 404 })
    }

    return NextResponse.json({ data: studio })
  } catch (err) {
    logger.error({ err }, 'GET /api/studio/profile: unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

export async function PATCH(request: NextRequest) {
  const auth = await getAuthenticatedUser()
  if (!auth) return NextResponse.json({ error: 'Unauthorized' }, { status: 401 })

  // Only owners can edit studio profile
  if (auth.role !== 'owner') {
    return NextResponse.json({ error: 'Only studio owners can update profile settings' }, { status: 403 })
  }

  const { success } = await authedRatelimit.limit(auth.user.id)
  if (!success) return NextResponse.json({ error: 'Too many requests' }, { status: 429 })

  let body: unknown
  try {
    body = await request.json()
  } catch {
    return NextResponse.json({ error: 'Invalid JSON' }, { status: 400 })
  }

  const parsed = UpdateStudioProfileSchema.safeParse(body)
  if (!parsed.success) {
    return NextResponse.json(
      { error: parsed.error.issues[0]?.message ?? 'Invalid request body' },
      { status: 422 },
    )
  }

  const update = parsed.data
  if (Object.keys(update).length === 0) {
    return NextResponse.json({ error: 'No fields to update' }, { status: 400 })
  }

  try {
    const supabase = await createClient()

    // If slug is being changed, verify uniqueness
    if (update.slug) {
      const { data: existing } = await supabase
        .from('studios')
        .select('id')
        .eq('slug', update.slug)
        .neq('id', auth.studioId)
        .maybeSingle()

      if (existing) {
        return NextResponse.json({ error: 'This URL slug is already taken' }, { status: 409 })
      }
    }

    const { error } = await supabase
      .from('studios')
      .update({ ...update, updated_at: new Date().toISOString() })
      .eq('id', auth.studioId)

    if (error) {
      logger.error({ err: error }, 'PATCH /api/studio/profile: supabase update error')
      return NextResponse.json({ error: 'Failed to update studio profile' }, { status: 500 })
    }

    await logAuditAction(supabase, {
      studioId: auth.studioId,
      userId: auth.user.id,
      action: 'studio.profile.updated',
      resourceType: 'studio',
      resourceId: auth.studioId,
      metadata: { fields: Object.keys(update) },
    })

    return NextResponse.json({ success: true })
  } catch (err) {
    logger.error({ err }, 'PATCH /api/studio/profile: unexpected error')
    return NextResponse.json({ error: 'Internal server error' }, { status: 500 })
  }
}

